func Benchmark_SplitUnescapedDelimiter(b *testing.B) {

	p := NewParameters()
	p.Characters.SetDelimiter(characters.Character_PIPE)
	r := NewRuntime(p, bufio.ScanLines)

	testData := GetTests()

	b.ResetTimer()
	for n := 0; n < b.N; n++ {
		for _, test := range testData {
			r.ParseUnescapedDelimiter(bytes.Split(test.args.data, p.Characters.Delimiter))
		}
	}
}

type TestArgs struct {
	data []byte
}
type TestData struct {
	name          string
	args          TestArgs
	want          [][]byte
	debug         bool
	delimiter     characters.Character
	enclosure     characters.Character
	colcount      int
	delimCount    uint32
	optionalDelim bool
	exclude       []int
	excel         bool
	php           bool
	skip          bool
}

